gcc is available. Write an LD_PRELOAD shim that intercepts unlink (and unlinkat too, just in case) and copies the file to /tmp/captured/ before deleting it.

Note: the shim needs to be position-independent and not interfere with other parts. Keep it minimal:

```c
#define _GNU_SOURCE
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <dlfcn.h>
#include <stdlib.h>
#include <libgen.h>

static void capture(const char *path) {
    if (!path) return;
    char dest[4096];
    const char *base = strrchr(path, '/');
    base = base ? base + 1 : path;
    snprintf(dest, sizeof(dest), "/tmp/captured/%s", base);
    FILE *src = fopen(path, "rb");
    if (!src) return;
    FILE *dst = fopen(dest, "wb");
    if (!dst) { fclose(src); return; }
    char buf[8192];
    size_t n;
    while ((n = fread(buf, 1, sizeof buf, src)) > 0)
        fwrite(buf, 1, n, dst);
    fclose(src);
    fclose(dst);
}

int unlink(const char *path) {
    static int (*real)(const char *) = NULL;
    if (!real) real = dlsym(RTLD_NEXT, "unlink");
    capture(path);
    return real(path);
}
int unlinkat(int dirfd, const char *path, int flags) {
    static int (*real)(int, const char *, int) = NULL;
    if (!real) real = dlsym(RTLD_NEXT, "unlinkat");
    if (dirfd == AT_FDCWD) capture(path);
    return real(dirfd, path, flags);
}
```

After that: mkdir /tmp/captured; gcc -shared -fPIC -o /tmp/shim.so /tmp/shim.c -ldl; cd /tmp/sb && LD_PRELOAD=/tmp/shim.so cobc -x -o bookforum src/program.cbl.

Write the shim with the write tool (it's a small C file, so it's acceptable — this is tooling, not the task's source. The task instructs to modify only the specified files, but creating temporary helper files inside /tmp should be fine — "files to be created or modified must be within this container" — and /tmp is inside the container. What the task restricts is changes to /app (the task's target file) and the test file. Helper files in /tmp are OK.)

