#define _GNU_SOURCE
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <dlfcn.h>

static void capture(const char *path)
{
	char dest[4096];
	const char *base;
	FILE *src, *dst;
	char buf[8192];
	size_t n;

	if (!path)
		return;
	base = strrchr(path, '/');
	base = base ? base + 1 : path;
	snprintf(dest, sizeof(dest), "/tmp/captured/%s", base);
	src = fopen(path, "rb");
	if (!src)
		return;
	dst = fopen(dest, "wb");
	if (!dst) {
		fclose(src);
		return;
	}
	while ((n = fread(buf, 1, sizeof buf, src)) > 0)
		fwrite(buf, 1, n, dst);
	fclose(src);
	fclose(dst);
}

int unlink(const char *path)
{
	static int (*real)(const char *) = NULL;
	if (!real)
		real = dlsym(RTLD_NEXT, "unlink");
	capture(path);
	return real(path);
}

int unlinkat(int dirfd, const char *path, int flags)
{
	static int (*real)(int, const char *, int) = NULL;
	if (!real)
		real = dlsym(RTLD_NEXT, "unlinkat");
	if (dirfd == AT_FDCWD)
		capture(path);
	return real(dirfd, path, flags);
}

