extern void cob_decimal_clear (cob_decimal *d);

static const cob_field_attr attr_10_0 = {0x10, 10, 0, 0x0000, NULL};
static const cob_field_attr attr_12_2 = {0x10, 12, 2, 0x0000, NULL};

static void dump(const char *label, const unsigned char *p, size_t n)
{
	size_t i;
	printf("%s: [", label);
	for (i = 0; i < n; i++)
		printf("%c", (p[i] >= 32 && p[i] < 127) ? p[i] : '?');
	printf("]");
	for (i = 0; i < n; i++)
		printf(" %02x", p[i]);
	printf("\n");
}

int main(int argc, char **argv)
{
	char *argv0[] = {"harness", NULL};
	cob_decimal d1, d2;
	unsigned char src10[10];
	unsigned char ws12[12];
	unsigned char bal10[10];
	unsigned char trans10[10];
	cob_field f_src, f_ws, f_bal, f_trans;

	cob_init(1, argv0);

	cob_decimal_init(&d1);
	cob_decimal_init(&d2);

	/* Test all provided input-amount byte patterns */
	int t = 0;
	while (t < argc - 2) {
		/* pattern passed as argv[t+2], may contain escapes: we pass raw bytes via env */
		t++;
	}

	/* Read patterns from file /tmp/patterns.bin: each line: raw bytes (no newline), one per line, length-prefixed by first byte count */
	FILE *fp = fopen("/tmp/patterns.bin", "rb");
	int n, rc;
	while (fp && (n = fgetc(fp)) != EOF) {
		memset(src10, ' ', sizeof src10);
		rc = fread(src10, 1, (size_t)n, fp);
		printf("=== INPUT-AMOUNT %d bytes ===\n", n);
		dump("src10", src10, 10);

		f_src.size = 10; f_src.data = src10; f_src.attr = &attr_10_0;

		/* MOVE to WS-AMOUNT (12, scale 2) */
		memset(ws12, ' ', sizeof ws12);
		f_ws.size = 12; f_ws.data = ws12; f_ws.attr = &attr_12_2;
		cob_move(&f_src, &f_ws);
		dump("ws12 after MOVE", ws12, 12);

		/* decimal of ws */
		cob_decimal_set_field(&d1, &f_ws);
		printf("ws decimal: value=%s scale=%d\n", mpz_get_str(NULL, 10, d1.value), d1.scale);

		/* MOVE to TRANS-AMOUNT (10, scale 0) */
		f_trans.size = 10; f_trans.data = trans10; f_trans.attr = &attr_10_0;
		cob_move(&f_ws, &f_trans);
		dump("trans10 after MOVE", trans10, 10);

		/* ADD ws to balance 1800 */
		memcpy(bal10, "0000001800", 10);
		f_bal.size = 10; f_bal.data = bal10; f_bal.attr = &attr_10_0;
		cob_add(&f_bal, &f_ws, 0);
		dump("bal after ADD 1800", bal10, 10);

		/* SUBTRACT ws from balance 1180 */
		memcpy(bal10, "0000001180", 10);
		cob_sub(&f_bal, &f_ws, 0);
		dump("bal after SUB 1180", bal10, 10);

		/* also: what does set_display see for bal-like raw data? test raw (pre-move) */
		cob_decimal_set_field(&d2, &f_src);
		printf("src10 decimal (raw, no move): value=%s scale=%d\n", mpz_get_str(NULL, 10, d2.value), d2.scale);
	}
	fclose(fp);

	cob_decimal_clear(&d1);
	cob_decimal_clear(&d2);
	cob_stop_run(0);
	return 0;
}

