    strncpy (file_open_name, file_open_env, ...);
    cob_chk_file_mapping ();
}
if (show_resolved_name && strcmp (file_open_env, file_open_name)) {
    sprintf (runtime_buffer, "%s ('%s' => %s)", file->select_name, file_open_env, file_open_name);
} else {
    sprintf (runtime_buffer, "%s ('%s')", file->select_name, file_open_env);
}
